.beautiful-ui {
  /* Compatibility aliases only. The source of truth is BoringUI's global
     theme, surface, interaction, and status palette. */
  --ink: var(--foreground);
  --ink-2: var(--muted-foreground);
  --ink-3: var(--muted-foreground);
  --line: var(--border);
  --line-strong: color-mix(in oklab, var(--foreground) 20%, transparent);
  --field: var(--accent);
  --stripe: color-mix(in oklab, var(--foreground) 8%, transparent);
  --stripe-bg: var(--muted);
  --hover-2: var(--active);

  --bui-focus: #6b97ff;
  --bui-focus-ink: color-mix(in srgb, var(--bui-focus) 62%, var(--foreground));
  --bui-focus-tint: color-mix(in srgb, var(--bui-focus) 15%, var(--background));
  --green-base: #22c55e;
  --green: color-mix(in srgb, var(--green-base) 62%, var(--foreground));
  --green-tint: color-mix(in srgb, var(--green-base) 15%, var(--background));
  --orange-base: #f97316;
  --orange: color-mix(in srgb, var(--orange-base) 62%, var(--foreground));
  --orange-tint: color-mix(in srgb, var(--orange-base) 15%, var(--background));
  --amber: #f59e0b;
  --cyan: #06b6d4;
  --purple: #a855f7;
  --red: color-mix(in srgb, var(--destructive) 68%, var(--foreground));
  --red-tint: var(--destructive-light);

  --tooltip-fg: var(--foreground);
  --tooltip-muted: var(--muted-foreground);
  --tooltip-border: var(--border);

  --shadow-hairline: var(--shadow-1);
  --shadow-btn: var(--shadow-2);
  --shadow-card: var(--shadow-3);
  --shadow-raised: var(--shadow-4);
  --shadow-overlay: var(--shadow-5);
  --shadow-inset-field: inset 0 0 0 1px var(--border);

  /* Size-aware radii. True pills opt into rounded-full explicitly; compact
     menus and cards must not inherit the app shell's 24px container radius. */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-menu: 10px;
  --radius-card: 12px;
  --radius-window: 14px;

  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", monospace;

  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);

  color: var(--ink);
  font-family: var(--font-sans);
}

.beautiful-ui[data-shape="rounded"] {
  --radius-chip: 4px;
  --radius-control: 6px;
  --radius-menu: 8px;
  --radius-card: 10px;
  --radius-window: 12px;
}

.beautiful-ui :is(h1, h2, h3, h4) {
  text-wrap: balance;
}

.beautiful-ui p {
  text-wrap: pretty;
}

.beautiful-ui .font-mono {
  font-family: var(--font-mono);
}

.beautiful-ui .font-medium {
  font-weight: 450;
  font-variation-settings: "wght" 450;
}

.beautiful-ui .font-semibold {
  font-weight: 550;
  font-variation-settings: "wght" 550;
}

.beautiful-ui .font-bold {
  font-weight: 700;
  font-variation-settings: "wght" 700;
}

.beautiful-ui ::selection {
  background: var(--bui-focus-tint);
  color: var(--ink);
}

.beautiful-ui button:not(:disabled),
.beautiful-ui [role="button"]:not([aria-disabled="true"]),
.beautiful-ui label:has(input),
.beautiful-ui a {
  cursor: pointer;
}

/* Keep text-entry resets below utilities so field surfaces, borders,
   typography, and deliberate shadows remain owned by each primitive.
   Native range and discrete controls retain their affordances. */
@layer base {
  .beautiful-ui
    :where(
      textarea,
      [contenteditable=""],
      [contenteditable="true" i],
      [contenteditable="plaintext-only" i],
      input:not([type]),
      input[type="text" i],
      input[type="search" i],
      input[type="email" i],
      input[type="url" i],
      input[type="tel" i],
      input[type="password" i],
      input[type="number" i]
    ) {
    -webkit-appearance: none;
    appearance: none;
    border: 0;
    background-color: transparent;
    box-shadow: none;
    font: inherit;
    color: inherit;
  }

  .beautiful-ui input[type="number" i] {
    -moz-appearance: textfield;
    appearance: textfield;
  }

  .beautiful-ui input[type="number" i]::-webkit-inner-spin-button,
  .beautiful-ui input[type="number" i]::-webkit-outer-spin-button {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
  }

  .beautiful-ui input[type="search" i]::-webkit-search-decoration,
  .beautiful-ui input[type="search" i]::-webkit-search-cancel-button,
  .beautiful-ui input[type="search" i]::-webkit-search-results-button,
  .beautiful-ui input[type="search" i]::-webkit-search-results-decoration {
    -webkit-appearance: none;
    appearance: none;
    display: none;
  }
}

.beautiful-ui :focus-visible {
  outline: 1px solid var(--bui-focus);
  outline-offset: 2px;
}

/* Standalone text fields retain a neutral focus boundary. Grouped fields
   delegate it to their surface, without changing fill or corner geometry. */
.beautiful-ui
  :is(
    textarea,
    [contenteditable=""],
    [contenteditable="true" i],
    [contenteditable="plaintext-only" i],
    input:not([type]),
    input[type="text" i],
    input[type="search" i],
    input[type="email" i],
    input[type="url" i],
    input[type="tel" i],
    input[type="password" i],
    input[type="number" i]
  ):focus {
  outline: 1px solid var(--line-strong);
  outline-offset: 2px;
}

/* Preserve the existing native-select exclusion; no primitive uses one. */
.beautiful-ui select:focus-visible {
  outline: none;
  outline-offset: 0;
}

.beautiful-ui :is([data-bui-input-group], [data-slot="input-group"]):focus-within {
  outline: 1px solid var(--line-strong);
  outline-offset: -1px;
}

.beautiful-ui [data-bui-input-group] [role="slider"]:focus {
  outline: none;
  outline-offset: 0;
}

.beautiful-ui
  :is([data-bui-input-group], [data-slot="input-group"])
  :is(
    textarea,
    [contenteditable=""],
    [contenteditable="true" i],
    [contenteditable="plaintext-only" i],
    input:not([type]),
    input[type="text" i],
    input[type="search" i],
    input[type="email" i],
    input[type="url" i],
    input[type="tel" i],
    input[type="password" i],
    input[type="number" i]
  ) {
  border: 0;
  background-color: transparent;
  box-shadow: none;
  outline: none;
  outline-offset: 0;
}

.beautiful-ui .animated-underline {
  position: relative;
  display: inline-block;
}

.beautiful-ui .animated-underline::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  content: "";
  background: currentColor;
